      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

interface IPunk {
    function punkIndexToAddress(uint256 punkIndex) external view returns (address);
}

interface IERC721 {
    function ownerOf(uint256 tokenId) external view returns (address);
    function transferFrom(address from, address to, uint256 tokenId) external;
    function setApprovalForAll(address operator, bool approved) external;
}

interface IPunks721 {
    function migrateLegacyWrappedPunks(uint256[] calldata punkIndexes) external;
}

contract CryptoPunkShadowAdapter {
    error NotOwner();
    error NotBeacon();
    error MustBeWrapped();

    address public immutable BEACON;
    address public constant CRYPTOPUNKS = 0xb47e3cd837dDF8e4c57F05d70Ab865de6e193BBB;
    address public constant PUNKS721 = 0x000000000000003607fce1aC9e043a86675C5C2F;
    address public constant WRAPPED_PUNKS = 0xb7F7F6C52F2e2fdb1963Eab30438024864c313F6;

    constructor(address _beacon) {
        BEACON = _beacon;

        // for converting legacy wrapped punks to 721
        IERC721(WRAPPED_PUNKS).setApprovalForAll(PUNKS721, true);
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner = IPunk(CRYPTOPUNKS).punkIndexToAddress(tokenId);

        if (owner == PUNKS721) {
            return IERC721(PUNKS721).ownerOf(tokenId);
        } else if (owner == WRAPPED_PUNKS) {
            return IERC721(WRAPPED_PUNKS).ownerOf(tokenId);
        } else {
            return owner;
        }
    }

    function transferFrom(address from, address to, uint256 tokenId) external {
        if (msg.sender != BEACON) revert NotBeacon();

        address owner = IPunk(CRYPTOPUNKS).punkIndexToAddress(tokenId);

        if (owner == PUNKS721) {
            IERC721(PUNKS721).transferFrom(from, to, tokenId);
        } else if (owner == WRAPPED_PUNKS) {
            IERC721(WRAPPED_PUNKS).transferFrom(from, address(this), tokenId);

            uint256[] memory punkIndexes = new uint256[](1);
            punkIndexes[0] = tokenId;
            IPunks721(PUNKS721).migrateLegacyWrappedPunks(punkIndexes);

            IERC721(PUNKS721).transferFrom(address(this), to, tokenId);
        } else {
            revert MustBeWrapped();
        }
    }
}
